with flagged as (select *, case when event_time - lag(event_time) over (partition by event_type order by event_time, id) > interval '90' day then 1 else 0 end as is_new_burst from web_events), sessions_web_events as (select id, event_type, page, event_time, sum(is_new_burst) over (partition by event_type order by event_time, id rows between unbounded preceding and current row) as session_id_2 from flagged) select date_trunc('quarter', event_time) as quarter_start, date_trunc('week', event_time) as week_start, round(sum(session_id_2) / nullif(count(case when event_type = 'click' then 1 end), 0), 2) as session_id_2_per_click, count(distinct id) as distinct_ids, size(collect_set(page)) as num_pages, dense_rank() over (partition by date_trunc('quarter', event_time) order by size(collect_set(page)) desc) as num_pages_dense_rank from sessions_web_events group by date_trunc('quarter', event_time), date_trunc('week', event_time) order by quarter_start desc;
